"""Actual 2006-mesh operational overview using the established whole-machine camera."""
import bpy,datetime,hashlib,json,sys,time
from pathlib import Path
from mathutils import Vector
H=Path(sys.argv[sys.argv.index('--')+1]);sys.path.insert(0,str(H.parent));from extract_scene import meshes
bpy.ops.wm.read_factory_settings(use_empty=True);scene=bpy.context.scene;materials={};records=[];started=time.monotonic()
for m in meshes(H/'full_scene_meshes.json.gz'):
 name=m['name'];v=m['vertices'];ii=m['indices'];data=bpy.data.meshes.new(name);data.from_pydata(list(zip(v[::3],v[1::3],v[2::3])),[],list(zip(ii[::3],ii[1::3],ii[2::3])));data.update();o=bpy.data.objects.new(name,data);scene.collection.objects.link(o);o['source_mesh_name']=name;o.color=tuple(m.get('color',[.5,.5,.5,1]));rgba=tuple(o.color)
 if rgba not in materials:
  mat=bpy.data.materials.new('source_'+str(len(materials)));mat.use_nodes=True;bs=mat.node_tree.nodes.get('Principled BSDF');bs.inputs['Base Color'].default_value=rgba;bs.inputs['Roughness'].default_value=.6;materials[rgba]=mat
 data.materials.append(materials[rgba]);records.append({'name':name,'vertices':len(v)//3,'triangles':len(ii)//3})
print('WHOLE_GEOMETRY_LOADED',len(records),time.monotonic()-started,flush=True)
assert len(records)==2006 and len({r['name']for r in records})==2006
scene.world=bpy.data.worlds.new('overview_world');scene.world.color=(.90,.93,.95);scene.render.engine='CYCLES';scene.cycles.device='CPU';scene.cycles.samples=12;scene.cycles.use_denoising=False;scene.cycles.max_bounces=4;scene.cycles.diffuse_bounces=2;scene.cycles.glossy_bounces=2;scene.world.use_nodes=True;scene.world.node_tree.nodes['Background'].inputs['Color'].default_value=(.82,.88,.94,1);scene.world.node_tree.nodes['Background'].inputs['Strength'].default_value=.75;scene.render.threads_mode='FIXED';scene.render.threads=1;shade=scene.display.shading;shade.light='STUDIO';shade.color_type='OBJECT';shade.show_shadows=True;shade.show_cavity=False;shade.background_type='WORLD';scene.display.render_aa='8'
for loc,power in [((-7,-6,10),1800),((-5,6,6),1200)]:
 bpy.ops.object.light_add(type='AREA',location=loc);li=bpy.context.object;li.data.energy=power;li.data.size=8;li.rotation_euler=(Vector((-4,.3,.55))-li.location).to_track_quat('-Z','Y').to_euler()
cd=bpy.data.cameras.new('whole_operational_camera');camera=bpy.data.objects.new(cd.name,cd);scene.collection.objects.link(camera);scene.camera=camera;cd.type='ORTHO';cd.clip_start=.001;cd.clip_end=100;eye=(-7,-12,8);target=(-4,.3,.55);camera.location=eye;camera.rotation_euler=(Vector(target)-camera.location).to_track_quat('-Z','Y').to_euler();cd.ortho_scale=13.;scene.render.resolution_x=1400;scene.render.resolution_y=900;scene.render.resolution_percentage=100;scene.render.image_settings.file_format='PNG';scene.render.filepath=str(H/'whole_operational_assembly.png');bpy.ops.render.render(write_still=True)
now=datetime.datetime.now(datetime.timezone.utc);d={'schema':'gtsd-whole-operational-render-v1','completed_utc':now.isoformat(),'completed_beijing':now.astimezone(datetime.timezone(datetime.timedelta(hours=8))).isoformat(),'source_full_scene_sha256':hashlib.sha256((H/'full_scene_meshes.json.gz').read_bytes()).hexdigest(),'profile_id':'operational_assembly_v1','mesh_count':len(records),'triangles':sum(r['triangles']for r in records),'geometry_reduced':False,'geometry_modified':False,'physics_pose':'static engineering assembly','render_engine':'CYCLES','samples':12,'denoising':False,'render_threads':1,'render_aa':'8','resolution':[1400,900],'camera_eye_m':eye,'camera_target_m':target,'ortho_scale_m':13.,'camera_basis':'existing published whole_candidate overview','render_seconds':time.monotonic()-started,'file':'whole_operational_assembly.png','sha256':hashlib.sha256((H/'whole_operational_assembly.png').read_bytes()).hexdigest(),'records':records};(H/'whole_operational_render_validation.json').write_text(json.dumps(d,indent=2)+'\n');print('WHOLE_RENDER_PASS',len(records),d['render_seconds'])
